// Founder OS · Automation Library — static site. Data comes from catalog.json and
// notion-schema.json, both generated by `python -m n8n.build`.

const REPO = "https://github.com/JavierMonestel/founder-os-automations";
const $ = (sel) => document.querySelector(sel);
const esc = (s) => String(s ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]);

const NODE_STYLE = {
  webhook: { fill: "#fff7ed", stroke: "#fdba74", label: "Webhook" },
  scheduleTrigger: { fill: "#fff7ed", stroke: "#fdba74", label: "Schedule" },
  httpRequest: { fill: "#eef2ff", stroke: "#a5b4fc", label: "HTTP" },
  code: { fill: "#f0fdfa", stroke: "#5eead4", label: "Code" },
  respondToWebhook: { fill: "#fdf2f8", stroke: "#f9a8d4", label: "Respond" },
};

function flowSvg(wf) {
  // Layered left-to-right layout, matching the positions in the n8n file.
  const parents = Object.fromEntries(wf.nodes.map((n) => [n.name, wf.edges.filter((e) => e[1] === n.name).map((e) => e[0])]));
  const depth = {};
  for (const n of wf.nodes) depth[n.name] = 1 + Math.max(-1, ...parents[n.name].map((p) => depth[p]));
  const rows = {};
  const pos = {};
  const W = 132, H = 46, GX = 30, GY = 14;
  for (const n of wf.nodes) {
    const d = depth[n.name];
    rows[d] = (rows[d] ?? -1) + 1;
    pos[n.name] = { x: 10 + d * (W + GX), y: 10 + rows[d] * (H + GY) };
  }
  const width = 20 + (Math.max(...Object.values(depth)) + 1) * (W + GX) - GX;
  const height = 20 + (Math.max(...Object.values(rows)) + 1) * (H + GY) - GY;
  const edges = wf.edges
    .map(([a, b]) => {
      const p = pos[a], q = pos[b];
      const x1 = p.x + W, y1 = p.y + H / 2, x2 = q.x, y2 = q.y + H / 2, mx = (x1 + x2) / 2;
      return `<path d="M${x1},${y1} C${mx},${y1} ${mx},${y2} ${x2},${y2}" fill="none" stroke="#cbd5e1" stroke-width="1.5" marker-end="url(#arrow)"/>`;
    })
    .join("");
  const nodes = wf.nodes
    .map((n) => {
      const s = NODE_STYLE[n.type] ?? NODE_STYLE.code;
      const { x, y } = pos[n.name];
      const name = n.name.length > 22 ? n.name.slice(0, 21) + "…" : n.name;
      return `<g><title>${esc(n.name)}${n.notes ? " — " + esc(n.notes) : ""}</title>
        <rect x="${x}" y="${y}" width="${W}" height="${H}" rx="9" fill="${s.fill}" stroke="${s.stroke}"/>
        <text x="${x + 10}" y="${y + 18}" font-size="9.5" fill="#64748b" font-family="JetBrains Mono, monospace">${s.label}</text>
        <text x="${x + 10}" y="${y + 34}" font-size="11.5" fill="#0f172a" font-family="Inter, sans-serif" font-weight="600">${esc(name)}</text></g>`;
    })
    .join("");
  return `<svg viewBox="0 0 ${width} ${height}" style="width:100%;max-width:${width}px;height:auto" xmlns="http://www.w3.org/2000/svg">
    <defs><marker id="arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M0,0 L10,5 L0,10 z" fill="#94a3b8"/></marker></defs>
    ${edges}${nodes}</svg>`;
}

function renderWorkflows(catalog) {
  $("#kpi-hours").textContent = `~${Math.round(catalog.total_hours_saved_per_month)}`;
  $("#kpi-workflows").textContent = catalog.workflows.length;
  $("#workflow-grid").innerHTML = catalog.workflows
    .map(
      (wf) => `<article class="card wf">
        <div class="wf-text">
          <h3>${esc(wf.name)}</h3>
          <div class="trigger">⏱ ${esc(wf.trigger)} · ${wf.nodes.length} nodes</div>
          <p>${esc(wf.description)}</p>
          <div class="chips">${wf.tools.map((t) => `<span class="chip">${esc(t)}</span>`).join("")}</div>
        </div>
        <div class="flow">${flowSvg(wf)}</div>
        <div class="wf-foot">
          <span class="saving"><b>${wf.hours_saved_per_month} h</b>/month saved · ${wf.minutes_saved_per_run} min × ${wf.runs_per_month} runs</span>
          <span>
            <a class="btn" href="${REPO}/blob/main/${wf.file}" target="_blank" rel="noopener">View</a>
            <a class="btn btn-dark" href="workflows/${wf.slug}.json" download>⬇ n8n JSON</a>
          </span>
        </div>
      </article>`,
    )
    .join("");
}

// ---------------------------------------------------------------- audit tool

const AUDIT_KEY = "founder-os-audit:v1";
const EXAMPLES = [
  ["Turn meeting notes into tasks in Linear/Attio", 25, 40, 3],
  ["Write the founder's morning brief", 20, 21, 2],
  ["Chase overdue follow-ups", 15, 21, 1],
  ["Monthly goals → Linear planning", 180, 1, 3],
  ["Investor update first draft", 120, 1, 2],
  ["Trip planning and calendar holds", 45, 3, 2],
  ["Weekly metrics into the Notion dashboard", 30, 4, 2],
  ["Expense receipts to the finance sheet", 10, 30, 2],
];

let rows = load();

function load() {
  try {
    const saved = JSON.parse(localStorage.getItem(AUDIT_KEY));
    if (Array.isArray(saved) && saved.length) return saved;
  } catch {}
  return EXAMPLES.map((r) => [...r]);
}

function save() {
  try {
    localStorage.setItem(AUDIT_KEY, JSON.stringify(rows));
  } catch {}
}

function renderAudit() {
  const scored = rows.map((r, i) => {
    const hours = (Number(r[1]) * Number(r[2])) / 60;
    const effort = Math.min(5, Math.max(1, Number(r[3]) || 1));
    return { i, hours, score: hours / effort };
  });
  const order = [...scored].sort((a, b) => b.score - a.score).map((s) => s.i);
  $("#audit-table tbody").innerHTML = rows
    .map((r, i) => {
      const s = scored[i];
      return `<tr>
        <td><input aria-label="Process" data-i="${i}" data-k="0" value="${esc(r[0])}"></td>
        <td><input aria-label="Minutes per run" type="number" min="0" data-i="${i}" data-k="1" value="${r[1]}"></td>
        <td><input aria-label="Runs per month" type="number" min="0" data-i="${i}" data-k="2" value="${r[2]}"></td>
        <td><input aria-label="Effort" type="number" min="1" max="5" data-i="${i}" data-k="3" value="${r[3]}"></td>
        <td class="num">${s.hours.toFixed(1)}</td>
        <td><span class="rank" title="Priority rank">#${order.indexOf(i) + 1}</span> <span class="num">${s.score.toFixed(1)}</span></td>
        <td><button class="remove" aria-label="Remove row" data-remove="${i}">✕</button></td>
      </tr>`;
    })
    .join("");
  const total = scored.reduce((s, x) => s + x.hours, 0);
  const top = order.slice(0, 3).map((i) => `<b>${esc(rows[i][0])}</b>`);
  $("#audit-summary").innerHTML = rows.length
    ? `These ${rows.length} processes cost about <b>${total.toFixed(1)} hours a month</b> (≈ ${(total / 160).toFixed(1)} weeks of a full-time person). Automate in this order: ${top.join(" → ")}.`
    : "Add the recurring processes you want to audit.";
}

function wireAudit() {
  $("#audit-table").addEventListener("input", (e) => {
    const t = e.target;
    if (!t.dataset.i) return;
    rows[+t.dataset.i][+t.dataset.k] = t.dataset.k === "0" ? t.value : Number(t.value);
    save();
    // Re-render only the computed cells to keep focus in the input being edited.
    const keep = document.activeElement?.dataset;
    renderAudit();
    if (keep?.i) document.querySelector(`input[data-i="${keep.i}"][data-k="${keep.k}"]`)?.focus();
  });
  $("#audit-table").addEventListener("click", (e) => {
    const i = e.target.dataset?.remove;
    if (i === undefined) return;
    rows.splice(+i, 1);
    save();
    renderAudit();
  });
  $("#add-row").addEventListener("click", () => {
    rows.push(["New recurring process", 15, 4, 2]);
    save();
    renderAudit();
  });
  $("#reset-rows").addEventListener("click", () => {
    rows = EXAMPLES.map((r) => [...r]);
    save();
    renderAudit();
  });
}

// ---------------------------------------------------------------- Notion OS

function renderNotion(schema) {
  const dbs = schema.databases;
  const pos = {
    objectives: [40, 40], key_results: [330, 20], projects: [330, 150],
    meetings: [40, 250], decisions: [620, 230], follow_ups: [620, 330],
  };
  const W = 200, H = 64;
  const center = (k) => [pos[k][0] + W / 2, pos[k][1] + H / 2];
  const lines = dbs
    .flatMap((db) => db.relations.map((r) => [db.key, r.target, r.name]))
    .map(([a, b]) => {
      const [x1, y1] = center(a), [x2, y2] = center(b);
      return `<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="#99f6e4" stroke-width="2.5"/>`;
    })
    .join("");
  const boxes = dbs
    .map((db) => {
      const [x, y] = pos[db.key];
      return `<g><rect x="${x}" y="${y}" width="${W}" height="${H}" rx="12" fill="#fff" stroke="#cbd5e1"/>
        <text x="${x + 14}" y="${y + 27}" font-size="15" font-weight="600" font-family="Inter, sans-serif" fill="#0f172a">${db.icon} ${esc(db.title)}</text>
        <text x="${x + 14}" y="${y + 47}" font-size="11.5" font-family="Inter, sans-serif" fill="#64748b">${db.properties.length + db.relations.length} properties</text></g>`;
    })
    .join("");
  $("#erd").setAttribute("viewBox", "0 0 860 420");
  $("#erd").innerHTML = lines + boxes;

  $("#db-grid").innerHTML = dbs
    .map((db) => {
      const props = db.properties.map((p) => `<li><span>${esc(p.name)}</span><span class="t">${p.type}</span></li>`);
      const rels = db.relations.map((r) => {
        const target = dbs.find((d) => d.key === r.target);
        return `<li class="rel"><span>${esc(r.name)}</span><span class="t">↔ ${esc(target.title)}</span></li>`;
      });
      const back = dbs.flatMap((d) => d.relations.filter((r) => r.target === db.key).map((r) => `<li class="rel"><span>${esc(r.back_name)}</span><span class="t">↔ ${esc(d.title)}</span></li>`));
      return `<article class="card db"><h3>${db.icon} ${esc(db.title)}</h3><p>${esc(db.description)}</p><ul class="props">${[...props, ...rels, ...back].join("")}</ul></article>`;
    })
    .join("");
}

// ---------------------------------------------------------------- prompts

const PROMPTS = [
  ["Meeting recap & actions", "meeting-recap-and-actions", "Transcript → JSON summary, decisions and routed action items, each with a verbatim quote."],
  ["Founder daily brief", "founder-daily-brief", "Company snapshot → a 60-second Slack brief that leads with what needs the founder."],
  ["Follow-up nudge", "follow-up-nudge", "Overdue items → one friendly, specific Slack nudge per owner. No guilt, no invented dates."],
  ["Investor update draft", "investor-update-draft", "KRs + shipped work → a sourced monthly update draft with honest lowlights and [CHECK] flags."],
  ["Travel planner", "travel-planner", "Trip request → two itinerary options, calendar holds, conflicts and a checklist. Never books."],
  ["Inbox triage", "inbox-triage", "Threads → reply / delegate / track / archive, with drafts that never commit the founder."],
];

function renderPrompts() {
  $("#prompt-grid").innerHTML = PROMPTS.map(
    ([title, slug, blurb]) => `<a class="card prompt" href="${REPO}/blob/main/prompts/${slug}.md" target="_blank" rel="noopener"><h3>${esc(title)} ↗</h3><p>${esc(blurb)}</p></a>`,
  ).join("");
}

// ---------------------------------------------------------------- boot

(async function main() {
  renderPrompts();
  wireAudit();
  renderAudit();
  const [catalog, schema] = await Promise.all([fetch("catalog.json").then((r) => r.json()), fetch("notion-schema.json").then((r) => r.json())]);
  renderWorkflows(catalog);
  renderNotion(schema);
})();
